-- Basic index on a single column
CREATE INDEX idx_users_email ON users(email);

-- Concurrent index creation (does not lock the table)
CREATE INDEX CONCURRENTLY idx_posts_user_id ON posts(user_id);

-- Composite index (order matters)
CREATE INDEX idx_orders_user_status ON orders(user_id, status);
-- Useful for: WHERE user_id = 1 AND status = 'pending'
-- Also useful for: WHERE user_id = 1 (uses the leftmost column)
-- NOT useful for: WHERE status = 'pending' only (skips leftmost column)

-- Partial index — index only a subset of rows
CREATE INDEX idx_orders_pending ON orders(created_at)
  WHERE status = 'pending';
-- Much smaller, much faster for: WHERE status = 'pending' ORDER BY created_at

-- Index on expression
CREATE INDEX idx_users_email_lower ON users(LOWER(email));
-- Supports: WHERE LOWER(email) = 'alice@example.com'
